		QueryBuilder<CarItem, String> qb = carsDao.queryBuilder();
		List<CarItem> list = new ArrayList<CarItem>();
		try {
			list = qb.query();
		} catch (SQLException e) {
			e.printStackTrace();
		}

		return list;
	}

